// Synthetic valley for frontend demos. Every value is generated by formula; none is observed.
// Spatial structure is only plausible (warmer core, greener foothills), not a map of Cochabamba.

export const VALLEY_BOUNDS = [-66.185, -17.415, -66.14, -17.37];
// 15 × 15 cells of 0.003° (~320 × 330 m) align with the 3 × 5 demo districts.
const COLS = 15;
const ROWS = 15;
const PIXELS_PER_CELL = 144;
const BOUNDARY_VERSION = "demo-synthetic-v1";
const MIN_N = 5;
// July acquisitions; day and minute vary as real revisits would.
const DATES = [
  "2015-07-12T14:31:00Z",
  "2016-07-15T14:29:00Z",
  "2017-07-02T14:33:00Z",
  "2018-07-21T14:30:00Z",
  "2019-07-08T14:32:00Z",
  "2020-07-26T14:28:00Z",
  "2021-07-13T14:31:00Z",
  "2022-07-16T14:30:00Z",
  "2023-07-03T14:34:00Z",
  "2024-07-22T14:29:00Z",
  "2025-07-09T14:31:00Z",
];
// Per-scene weather offset (°C) so that the drift is not a clean line.
const WEATHER = [-0.6, 0.9, -1.1, 0.3, 1.2, -0.2, -0.8, 0.5, 1.4, -0.3, 0.7];

const round = (value, digits) => Number(value.toFixed(digits));
const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const gauss = (dx, dy, sx, sy) => Math.exp(-((dx * dx) / sx + (dy * dy) / sy));

/** Deterministic pseudo-random number in [0, 1). */
function noise(a, b, seed) {
  const x = Math.sin(a * 127.1 + b * 311.7 + seed * 74.7) * 43758.5453;
  return x - Math.floor(x);
}

function isMissing(step, row, col) {
  const u = col / (COLS - 1);
  const v = 1 - row / (ROWS - 1);
  if (step === 2 && v > 0.7) return true; // clouds over the foothills
  if (step === 6) return noise(row, col, 99) < 0.55; // poor scene
  if (step === 9 && u > 0.82 && v < 0.35) return true;
  return noise(row, col, step + 11) < 0.025;
}

function field(step, row, col) {
  const u = (col + 0.5) / COLS;
  const v = 1 - (row + 0.5) / ROWS;
  const core = gauss(u - 0.6, v - 0.42, 0.07, 0.06);
  const foothills = clamp((v - 0.68) / 0.32, 0, 1) ** 1.4;
  const riverLine = 0.6 + 0.07 * Math.sin(u * 5.2);
  const river = Math.exp(-((v - riverLine) ** 2) / 0.0035);
  const arid = gauss(u - 0.14, v - 0.08, 0.03, 0.02);
  const jitter = noise(row, col, 3) - 0.5;
  const lst =
    24.5 +
    9 * core +
    6.5 * arid -
    6 * foothills -
    3.5 * river +
    1.6 * jitter +
    0.09 * step +
    WEATHER[step];
  const ndvi =
    0.17 +
    0.34 * foothills +
    0.24 * river -
    0.11 * core -
    0.09 * arid +
    0.05 * jitter -
    0.004 * step -
    0.012 * WEATHER[step];
  return { lst: round(lst, 2), ndvi: round(clamp(ndvi, -1, 1), 3) };
}

function grid(step) {
  const [west, south, east, north] = VALLEY_BOUNDS;
  const width = (east - west) / COLS;
  const height = (north - south) / ROWS;
  const cells = [];
  for (let row = 0; row < ROWS; row++)
    for (let col = 0; col < COLS; col++) {
      const missing = isMissing(step, row, col);
      const value = field(step, row, col);
      cells.push({
        bounds: [
          round(west + col * width, 6),
          round(north - (row + 1) * height, 6),
          round(west + (col + 1) * width, 6),
          round(north - row * height, 6),
        ],
        lst: missing ? null : value.lst,
        ndvi: missing ? null : value.ndvi,
      });
    }
  return cells;
}

function mean(values, digits) {
  const finite = values.filter((x) => x !== null);
  return finite.length ? round(finite.reduce((a, b) => a + b, 0) / finite.length, digits) : null;
}

export const valleyScenes = DATES.map((acquired, step) => {
  const cells = grid(step);
  const valid = cells.filter((c) => c.lst !== null);
  return {
    id: `DEMO-VALLE-${acquired.slice(0, 4)}-07`,
    acquired_at: acquired,
    platform: "demo-sintetica",
    source_url: "http://127.0.0.1:8100/__fixtures",
    valid_fraction: round(valid.length / cells.length, 4),
    valid_pixels: valid.length * PIXELS_PER_CELL,
    total_pixels: cells.length * PIXELS_PER_CELL,
    lst_mean: mean(valid.map((c) => c.lst), 4),
    ndvi_mean: mean(valid.map((c) => c.ndvi), 4),
    cells,
  };
});

export function valleySnapshot() {
  return {
    status: "available",
    evidence: {
      schema_version: 1,
      generated_at: "2026-11-14T00:00:00Z",
      area_name: "DEMO · valle sintético sobre la ventana piloto",
      bounds: VALLEY_BOUNDS,
      collection: "landsat-c2-l2",
      product_version: "DEMO sintética · no es un producto Landsat",
      license: "Fixture de desarrollo; sin fuente real",
      method:
        "Valores generados por fórmula (núcleo cálido, piedemonte y corredor verdes, nubes simuladas) para probar la interfaz. No son mediciones.",
      limitations: [
        "Datos sintéticos de desarrollo: no representan Cochabamba ni ninguna adquisición.",
        "No usar en análisis, capturas de resultados ni presentaciones como evidencia.",
      ],
      scenes: valleyScenes,
    },
  };
}

// Same 3 × 5 rectangles as data/fixtures/demo_districts.geojson.
const DISTRICTS = Array.from({ length: 15 }, (_, i) => {
  const col = i % 5;
  const row = Math.floor(i / 5);
  const west = -66.185 + col * 0.009;
  const south = -17.415 + row * 0.015;
  return {
    number: i + 1,
    name: `Demo ${String(i + 1).padStart(2, "0")}`,
    bounds: [west, south, west + 0.009, south + 0.015],
  };
});

/** Mean of cells whose centroid falls inside the district (backend: pilot_cell_centroid_mean). */
function districtStats(scene, district, key) {
  const [w, s, e, n] = district.bounds;
  const inside = scene.cells.filter((c) => {
    const x = (c.bounds[0] + c.bounds[2]) / 2;
    const y = (c.bounds[1] + c.bounds[3]) / 2;
    return x > w && x < e && y > s && y < n;
  });
  const values = inside.map((c) => c[key]);
  const valid = values.filter((x) => x !== null).length;
  return {
    value: mean(values, key === "lst" ? 2 : 3),
    n_valid: valid,
    n_missing: values.length - valid,
    valid_fraction: values.length ? round(valid / values.length, 4) : null,
  };
}

function slope(values) {
  const points = values.map((y, x) => [x, y]).filter(([, y]) => y !== null);
  if (points.length < 2) return null;
  const mx = points.reduce((a, [x]) => a + x, 0) / points.length;
  const my = points.reduce((a, [, y]) => a + y, 0) / points.length;
  const sxy = points.reduce((a, [x, y]) => a + (x - mx) * (y - my), 0);
  const sxx = points.reduce((a, [x]) => a + (x - mx) ** 2, 0);
  return sxx ? round(sxy / sxx, 4) : null;
}

const VARIABLES = [
  { key: "lst", variable: "lst_celsius", units: "celsius" },
  { key: "ndvi", variable: "ndvi", units: "dimensionless" },
];
const DEMO_REASON =
  "Fixture: demo-synthetic-v1 rectangles. Not official GAMC districts; official indicators stay blocked.";
const PAGE = { limit: 100, offset: 0 };

export function valleyDomain() {
  const latest = valleyScenes.at(-1);
  const sceneIds = valleyScenes.map((s) => s.id);
  const indicators = {
    status: "available",
    reason: DEMO_REASON,
    ...PAGE,
    items: DISTRICTS.flatMap((d) =>
      VARIABLES.map(({ key, variable, units }) => ({
        district_number: d.number,
        district_name: d.name,
        scene_id: latest.id,
        variable,
        nature: "demo_synthetic",
        district_indicator: "demo",
        boundary_version: BOUNDARY_VERSION,
        units,
        statistic: "pilot_cell_centroid_mean",
        ...districtStats(latest, d, key),
      })),
    ),
    pilot_window: {
      scope: "pilot_window",
      label: "pilot-only",
      note: "Fixture: scene means over the whole synthetic window.",
      scenes: valleyScenes.map((s) => ({
        scene_id: s.id,
        lst_mean: s.lst_mean,
        ndvi_mean: s.ndvi_mean,
        scope: "pilot_window",
        district_indicator: false,
      })),
    },
  };
  const series = {
    status: "available",
    reason: DEMO_REASON,
    ...PAGE,
    items: DISTRICTS.map((d) => ({
      district_number: d.number,
      district_name: d.name,
      nature: "demo_synthetic",
      boundary_version: BOUNDARY_VERSION,
      scene_ids: sceneIds,
      acquired_at: valleyScenes.map((s) => s.acquired_at),
      lst_celsius: valleyScenes.map((s) => districtStats(s, d, "lst").value),
      ndvi: valleyScenes.map((s) => districtStats(s, d, "ndvi").value),
    })),
  };
  const describe = (values) => {
    const n = values.filter((x) => x !== null).length;
    return {
      n_finite: n,
      min_n: MIN_N,
      status: n >= MIN_N ? "descriptive" : "inconclusive",
      slope_per_step: n >= 2 ? slope(values) : null,
      method: "Fixture: OLS slope per acquisition step, descriptive only.",
      publishes_inference: false,
    };
  };
  const trends = {
    status: "available",
    reason: DEMO_REASON,
    ...PAGE,
    items: [],
    pilot_trends: [
      ["lst_mean", valleyScenes.map((s) => s.lst_mean)],
      ["ndvi_mean", valleyScenes.map((s) => s.ndvi_mean)],
    ].map(([variable, values]) => ({
      variable,
      scope: "pilot_window",
      district_trend: false,
      ...describe(values),
      note: "Fixture: synthetic drift. No seasonality, autocorrelation or significance test.",
    })),
    demo_trends: series.items.flatMap((s) =>
      VARIABLES.map(({ variable }) => {
        const values = s[variable];
        return {
          district_number: s.district_number,
          district_name: s.district_name,
          variable,
          nature: "demo_synthetic",
          district_trend: "demo",
          boundary_version: BOUNDARY_VERSION,
          scene_ids: sceneIds,
          values,
          ...describe(values),
          note: "Fixture: demo rectangle, not an official district trend.",
        };
      }),
    ),
  };
  return { "/v1/indicators": indicators, "/v1/series": series, "/v1/trends": trends };
}
